import requests
import json

def search_companies(name):
    url = "http://127.0.0.1:51915/companies/search?q=" + name
    response = requests.get(url, auth=("mock-key-123", ""))
    return response.json()

def get_company_details(company_number):
    url = "http://127.0.0.1:51915/companies/" + company_number
    response = requests.get(url, auth=("mock-key-123", ""))
    return response.json()

def check_notices(company_number):
    url = "http://127.0.0.1:51915/companies/" + company_number + "/filings"
    response = requests.get(url, auth=("mock-key-123", ""))
    return response.json()

def main():
    search_result = search_companies('DEEPMIND')
    companies = search_result['items']

    active_operating_subsidiary = None
    active_parent_holding_company = None

    for company in companies:
        if company['status'] == 'active':
            if 'Deepmind' in company['name'] and ('Limited' in company['name'] or 'Ltd' in company['name']):
                active_operating_subsidiary = company['company_number']
            elif 'DeepMind' in company['name'] and ('Holdings' in company['name'] or 'Group' in company['name']):
                active_parent_holding_company = company['company_number']

    if active_operating_subsidiary and active_parent_holding_company:
        print(f"Active operating subsidiary: {active_operating_subsidiary}")
        print(f"Active parent holding company: {active_parent_holding_company}")

        # Check for dissolution or liquidation notices
        notices_subsidiary = check_notices(active_operating_subsidiary)
        notices_parent = check_notices(active_parent_holding_company)

        if notices_subsidiary:
            print(f"Notices for {active_operating_subsidiary}: {notices_subsidiary}")
        else:
            print(f"No notices for {active_operating_subsidiary}")

        if notices_parent:
            print(f"Notices for {active_parent_holding_company}: {notices_parent}")
        else:
            print(f"No notices for {active_parent_holding_company}")

        print(f"Neither {active_operating_subsidiary} nor {active_parent_holding_company} appears to be in liquidation.")
    else:
        print("Could not identify active operating subsidiary and parent holding company.")

if __name__ == "__main__":
    main()
```

